param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'enum-type-receiver-guards-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Value($p){switch($p.kind){'null'{return $null};'object'{return [object]::new()};'string'{return [string]$p.value};'enum'{return [Enum]::ToObject([type]::GetType($p.enumType,$true),[int]$p.value)};'int32'{return [int]::Parse($p.value)};'int32Facade'{return [int]::Parse($p.value)};'int16'{return [int16]::Parse($p.value)};'int64'{return [int64]::Parse($p.value)};'sbyte'{return [sbyte]::Parse($p.value)};'sbytePrimitive'{return [sbyte]::Parse($p.value)};'byte'{return [byte]::Parse($p.value)};'uint16'{return [uint16]::Parse($p.value)};'uint32'{return [uint32]::Parse($p.value)};'uint64'{return [uint64]::Parse($p.value)};'bool'{return $p.value -eq '1'};'char'{return [char][int]$p.value};'single'{return [single]::Parse($p.value,[Globalization.CultureInfo]::InvariantCulture)};'double'{return [double]::Parse($p.value,[Globalization.CultureInfo]::InvariantCulture)};'decimal'{return [decimal]::Parse($p.value,[Globalization.CultureInfo]::InvariantCulture)};default{throw 'Unknown value profile'}}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=[Collections.Generic.List[object]]::new()
foreach($typeName in $plan.types){$type=[type]::GetType($typeName,$true);if($type.IsEnum){throw 'Nonenum receiver required'};foreach($method in $plan.methods){$objectArgument=$method -in @('GetEnumName','IsEnumDefined');$parameterTypes=[type[]]::new(0);if($objectArgument){$parameterTypes=[type[]]@([object])};$member=$type.GetType().GetMethod($method,$parameterTypes);$profiles=if($objectArgument){$plan.profiles}else{@([pscustomobject]@{kind='noarg';value=''})};foreach($p in $profiles){$arguments=[object[]]::new(0);if($objectArgument){$arguments=[object[]]::new(1)};if($objectArgument){$arguments[0]=Value $p};try{$member.Invoke($type,$arguments)|Out-Null;$result=[ordered]@{ok=$true}}catch{$result=Failure $_};$rows.Add([ordered]@{type=$typeName;method=$method;kind=$p.kind;value=$p.value;enumType=$(if($p.kind -eq 'enum'){$p.enumType}else{$null});result=$result})}}}
$expected=$plan.types.Count*(4+2*$plan.profiles.Count);if($rows.Count -ne $expected -or @($rows|Where-Object {$_.result.ok}).Count -ne 0){throw 'Nonenum guard matrix mismatch'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 20 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS nonenum receiver guards: $($rows.Count) failures across 29 receiver types"
